CREATE COLUMN TABLE "TEST_AP"."OPRA" ("AbsEntry" INTEGER CS_INT NOT NULL , "CateType" NVARCHAR(1) NOT NULL , "CateCode" NVARCHAR(8) NOT NULL , "Category" NVARCHAR(254), "Account" NVARCHAR(15), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
